FAMILIES = sorted({p["family"] for p in CATALOG})
def get_parameter(parameter_id):
    for item in CATALOG:
        if item["id"] == parameter_id:
            return dict(item)
    raise KeyError(f"Unknown parameter id: {parameter_id}")
def list_parameters(family=None):
    return [dict(p) for p in CATALOG if family is None or p["family"] == family]
